ruleContent.content:
$.data[?(@.hasContent==1)].content
<js>
//判断正文是否加密
pos=result.indexOf("\{\{\{\}\}\}");
pos==-1?result:result=java.aesBase64DecodeToString(result.slice(pos+6),"OW84U8Eerdb99rtsTXWSILDO","DESede/CBC/PKCS5Padding","SK8bncVu");
//错漏章过滤
/^[\s\S]{0,50}?(?:@font-face|\{\"code\":|此章节正在|防盗章|字数填充)|(?:正在手打中|努力更新中|内容更新后)\W+请[重稍在]|为防止内容获取不全和文字乱序|网站已经不更新最新章节|网站此章内容错误|…。。\r\s+！\f\s+$|\n\s+[\(“]\f\s+$|\u0000{9}\s+$/.exec(result)?'':result</js>

ruleBookInfo.author:
$.data.author##\{|\}
<js>
try{
var javaImport = new JavaImporter();
javaImport.importPackage(
    Packages.java.lang,
    Packages.javax.crypto,
    Packages.javax.crypto.spec,
    Packages.android.util
);
with(javaImport){
        var key=SecretKeySpec(String("OW84U8Eerdb99rtsTXWSILDO").getBytes(),"DESede");
        var iv=IvParameterSpec(String("SK8bncVu").getBytes());
        var bytes=Base64.decode(String(result).getBytes(),2);
        var chipher=Cipher.getInstance("DESede/CBC/PKCS5Padding");
        chipher.init(2,key,iv);
        result= String(chipher.doFinal(bytes));
}}catch(e){result}
</js>

